 );
}
","import React from "react";

const heat = (v: number) => {
 // 0 -> deep navy, 100 -> cyan
 const t = v / 100;
 const a = 0.08 + t * 0.85;
 return `rgba(53, 224, 255, ${a.toFixed(2)})`;
};

// ---------- Cohort / heatmap matrix ----------
export function CohortMatrix({ rows, cols, onCell }:
 { rows: { stage: string; cells: number[] }[]; cols: string[]; onCell?: (r: string, c: string, v: number) => void }) {
 return (
 <div style={{ overflowX: "auto" }}>
 <table style={{ borderCollapse: "separate", borderSpacing: 4, width: "100%" }}>
 <thead>
 <tr><th></th>{cols.map(c => <th key={c} style={{ fontSize: 9.5, color: "var(--ci-text-faint)", fontWeight: 600, padding: "0 2px", textAlign: "center" }}>{c}</th>)}</tr>
 </thead>
 <tbody>
 {rows.map(r => (
 <tr key={r.stage}>
 <td style={{ fontSize: 10.5, color: "var(--ci-text-dim)", whiteSpace: "nowrap", paddingRight: 8 }}>{r.stage}</td>
 {r.cells.map((v, i) => (
 <td key={i} title={`${r.stage} · ${cols[i]}: ${v}`} onClick={() => onCell?.(r.stage, cols[i], v)}
 style={{ background: heat(v), height: 30, borderRadius: 5, textAlign: "center", cursor: "pointer",
 fontSize: 10, color: v > 55 ? "#04121e" : "var(--ci-text-dim)", fontWeight: 600, transition: "transform .12s" }}>
 {v}
 </td>
 ))}
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 );
}

// ---------- Sport development matrix (restrained heat + rich hover + click) ----------
export function SportMatrix({ rows, cols, selected, onSelect }:
 { rows: { sport: string; cells: number[]; note: string }[]; cols: string[];
 selected: string | null; onSelect: (sport: string) => void }) {
 const [tip, setTip] = React.useState<{ x: number; y: number; sport: string; col: string; v: number; note: string } | null>(null);
 const prevDelta = (v: number) => (((v * 7) % 13) - 6); // deterministic pseudo change
 // meaningful stepped heat: weak / moderate / strong / exceptional
 const step = (v: number) =>
 v >= 80 ? { bg: "#12a06d", fg: "#ffffff" } :
 v >= 60 ? { bg: "rgba(10,153,199,0.62)", fg: "#08313f" } :
 v >= 40 ? { bg: "rgba(10,153,199,0.24)", fg: "#0a6f8f" } :
 { bg: "rgba(18,38,78,0.06)", fg: "var(--ci-text-faint)" };
 return (
 <div style={{ position: "relative", overflowX: "auto" }}>
 <table style={{ borderCollapse: "separate", borderSpacing: 4, width: "100%" }}>
 <thead>
 <tr><th style={{ width: 96 }}></th>{cols.map(c => (
 <th key={c} style={{ fontSize: 9, color: "var(--ci-text-faint)", fontWeight: 600, padding: "0 2px", textAlign: "center", letterSpacing: "0.02em" }}>{c}</th>
 ))}</tr>
 </thead>
 <tbody>
 {rows.map(r => {
 const dim = selected && selected !== r.sport;
 return (
 <tr key={r.sport} style={{ opacity: dim ? 0.4 : 1, transition: "opacity .15s" }}>
 <td onClick={() => onSelect(r.sport)}
 style={{ fontSize: 11, color: selected === r.sport ? "var(--ci-cyan)" : "var(--ci-text-dim)", whiteSpace: "nowrap", paddingRight: 8, cursor: "pointer", fontWeight: selected === r.sport ? 700 : 500 }}>
 {r.sport}
 </td>
 {r.cells.map((v, i) => {
 const st = step(v);
 return (
 <td key={i} onClick={() => onSelect(r.sport)}
 onMouseMove={e => setTip({ x: e.clientX, y: e.clientY, sport: r.sport, col: cols[i], v, note: r.note })}
 onMouseLeave={() => setTip(null)}
 style={{ background: st.bg, height: 26, borderRadius: 5,
 textAlign: "center", cursor: "pointer", fontSize: 10, fontWeight: 700, color: st.fg,
 outline: selected === r.sport ? "1.5px solid var(--ci-cyan)" : "none" }}>
 {v}
 </td>
 );
 })}
 </tr>
 );
 })}
 </tbody>
 </table>
 <div className="ci-legend" style={{ marginTop: 8 }}>
 {[["Weak", "rgba(18,38,78,0.10)"], ["Moderate", "rgba(10,153,199,0.24)"], ["Strong", "rgba(10,153,199,0.62)"], ["Exceptional", "#12a06d"]].map(([l, c]) => (
 <span key={l} className="ci-legend__item"><span className="ci-legend__swatch" style={{ background: c }} />{l}</span>
 ))}
 </div>
 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 12, top: tip.y - 10 }}>
 <b>{tip.sport} · {tip.col}</b><br />
 <span className="ci-faint">Pathway strength {tip.v}/100 · {prevDelta(tip.v) >= 0 ? "+" : ""}{prevDelta(tip.v)} vs prev</span><br />
 <span className="ci-faint">{tip.note}</span>
 </div>
 )}
 </div>
 );
}

// ---------- Risk matrix (likelihood x impact bubbles) ----------
export function RiskMatrix({ items }: { items: { x: number; y: number; label: string; count: number }[] }) {
 const size = 220, pad = 26, cell = (size - pad) / 5;
 const zone = (x: number, y: number) => (x + y >= 7 ? "var(--ci-red)" : x + y >= 5 ? "var(--ci-amber)" : "var(--ci-green)");
 return (
 <svg className="ci-chart" viewBox={`0 0 ${size} ${size}`} style={{ maxWidth: size + 40 }}>
 {[0, 1, 2, 3, 4].map(r => [0, 1, 2, 3, 4].map(c => (
 <rect key={`${r}-${c}`} x={pad + c * cell} y={r * cell} width={cell - 2} height={cell - 2} rx="3"
 fill={zone(c + 1, 5 - r)} fillOpacity="0.12" />
 )))}
 <text x={pad + (size - pad) / 2} y={size - 4} textAnchor="middle">Likelihood →</text>
 <text x={10} y={(size - pad) / 2} textAnchor="middle" transform={`rotate(-90 10 ${(size - pad) / 2})`}>Impact →</text>
 {items.map((it, i) => (
 <g key={i}>
 <circle cx={pad + (it.x - 0.5) * cell} cy={size - pad - (it.y - 0.5) * cell} r={6 + it.count / 6}
 fill={zone(it.x, it.y)} fillOpacity="0.8" stroke="#04121e" strokeWidth="1">
 <title>{it.label}: {it.count}</title>
 </circle>
 <text x={pad + (it.x - 0.5) * cell} y={size - pad - (it.y - 0.5) * cell + 3} textAnchor="middle"
 fontSize="9" fontWeight="700" fill="#04121e">{it.count}</text>
 </g>
 ))}
 </svg>
 );
}
