","import React from "react";
import { Drawer } from "../../Drawer";
import { ActionRow } from "../../Button";
import { Chip } from "../../KpiCard";
import { Bullet } from "../../charts/readiness";
import { CmdDrawerState } from "./ctx";
import { NATIONAL_CONVERSION_AVG } from "../../../data/command";

const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
const stat = (v: React.ReactNode, l: string) => (
 <div className="ci-stat"><span className="ci-stat__v">{v}</span><span className="ci-stat__l">{l}</span></div>
);

export function CmdDrawer({ state, onClose, onAction }:
 { state: CmdDrawerState | null; onClose: () => void; onAction: (a: string) => void }) {
 if (!state) return null;
 const { kind, data } = state;

 let title = "", sub = "", body: React.ReactNode = null, actions: string[] = [];

 if (kind === "kpi") {
 title = data.label; sub = data.drill;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(data.value.toLocaleString(), "Current")}
 {stat(<span style={{ color: data.delta >= 0 ? "var(--ci-green)" : "var(--ci-red)" }}>{data.delta >= 0 ? "+" : ""}{data.delta}%</span>, "Trend")}
 {stat(<Chip status={data.status}>{data.status}</Chip>, "Status")}
 </div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.support}. This opens the underlying filtered cohort in the analytics workspace.</p>
 </>;
 actions = ["Investigate", "Compare", "Add to Watchlist"];
 } else if (kind === "region") {
 title = data.name + " Region"; sub = `${data.discovered.toLocaleString()} discovered · ${data.conversion}% conversion`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(data.assessed.toLocaleString(), "Assessed")}
 {stat(data.highPotential, "High potential")}
 {stat(data.pathways.toLocaleString(), "Dev pathways")}
 {stat(data.velocity, "Dev velocity")}
 </div>
 {data.top3 && <>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Top 3 sports</div>
 <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>{data.top3.map((s: string, i: number) => <Chip key={s} status={i === 0 ? "cyan" : "ghost"}>{s}</Chip>)}</div>
 </>}
 <div className="ci-insight" style={{ marginBottom: 12 }}>
 <span className="ci-insight__icon">◆</span>
 <div className="ci-insight__txt" style={{ fontSize: 12 }}>{data.insight}
 {data.conversion < NATIONAL_CONVERSION_AVG && <> <b>({(NATIONAL_CONVERSION_AVG - data.conversion).toFixed(1)}pts below national average)</b></>}</div>
 </div>
 </>;
 actions = ["Investigate", "Create Intervention", "Request Assessment", "Add to Watchlist"];
 } else if (kind === "cycle") {
 title = `${data.year} Cycle Readiness`; sub = `${data.headline} · overall ${data.overall}%`;
 body = <>
 <div style={{ marginBottom: 14 }}>{data.dims.map((d: any) => <Bullet key={d.label} label={d.label} value={d.value} />)}</div>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Top contributing sports</div>
 <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 14 }}>{data.sports.map((s: string) => <Chip key={s} status="cyan">{s}</Chip>)}</div>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Cohort</div>
 <p className="ci-dim" style={{ fontSize: 12.5, margin: "0 0 14px" }}>{data.cohorts}</p>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Readiness gaps</div>
 <ul style={{ margin: "0 0 14px", paddingLeft: 16 }}>{data.gaps.map((g: string) => <li key={g} className="ci-dim" style={{ fontSize: 12.5, marginBottom: 4 }}>{g}</li>)}</ul>
 <div className="ci-insight"><span className="ci-insight__icon">◆</span><div className="ci-insight__txt" style={{ fontSize: 12 }}><b>Recommended:</b> {data.rec}</div></div>
 </>;
 actions = ["Recommend Development Plan", "Create Intervention"];
 } else if (kind === "risk") {
 title = data.subject; sub = `${data.sev} · open ${data.age}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(<Chip status={data.sev === "CRITICAL" ? "red" : data.sev === "HIGH" ? "amber" : "cyan"}>{data.sev}</Chip>, "Severity")}
 {stat(data.count, "Affected")}
 {stat(data.owner, "Owner")}
 {stat(data.age, "Time open")}
 </div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.issue}. Recommended next step: <b style={{ color: "var(--ci-text)" }}>{data.next}</b>.</p>
 </>;
 actions = ["Investigate", "Create Intervention", "Assign Specialist", "Schedule Assessment"];
 } else if (kind === "velo") {
 if (data) {
 title = data.name; sub = `${data.sport} · ${data.region} · age ${data.age} · ${data.stage}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 12, marginBottom: 14 }}>
 {stat("P" + data.perf, "Benchmark")}
 {stat(<span style={{ color: "var(--ci-green)" }}>+{data.growth}%</span>, "Improvement")}
 {stat(data.conf, "Confidence")}
 </div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.perf < 50 && data.growth > 50 ? "Emerging athlete accelerating faster than cohort — strong candidate for accelerated assessment." : "Tracking within expected development band."}</p>
 </>;
 actions = ["Open Athlete", "Compare", "Add to Watchlist", "Request Assessment"];
 } else {
 title = "Create Assessment Cohort"; sub = "17 high-velocity athletes · 3 sports · 2 regions";
 body = <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>Group the emerging high-velocity athletes into a focused assessment cohort and assign specialist coverage before the next cycle.</p>;
 actions = ["Create Intervention", "Assign Specialist", "Schedule Assessment"];
 }
 } else if (kind === "opp") {
 title = data.tag; sub = "Emerging opportunity";
 body = <>
 <div className="cc-opp__signal" style={{ marginBottom: 8 }}>{data.signal}</div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.why}</p>
 </>;
 actions = data.actions.concat(["Investigate"]);
 } else if (kind === "pipeline") {
 title = "Pathway Analysis"; sub = "Conversion & leakage across the national pipeline";
 body = <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>Detailed stage-by-stage conversion analysis. Largest leakage occurs at <b style={{ color: "var(--ci-amber)" }}>Validated → Development</b> (43% progression) — the clearest lever for expanding the development pool.</p>;
 actions = ["Investigate", "Create Intervention"];
 }

 return (
 <Drawer open onClose={onClose} title={title} sub={sub}
 footer={<ActionRow actions={actions} onAction={onAction} />}>
 {body}
 </Drawer>
 );
}
","import React from "react";
import "../../command.css";
import { useApp } from "../../context/AppContext";
import { CommandContext, CmdDrawerState, DrawerKind } from "./command/ctx";
import { CmdHeader } from "./command/CmdHeader";
import { KpiStrip } from "./command/KpiStrip";
import { PipelineRow } from "./command/PipelineRow";
import { MapRow, VelocityRow } from "./command/MapVelocityRow";
import { MatrixRow, OpportunitiesRow } from "./command/MatrixOppRow";
import { RisksRow, ActionCenterRow } from "./command/RiskActionRow";
import { AiInsightRow, ActivityRow } from "./command/AiActivityRow";
import { CmdDrawer } from "./command/CmdDrawer";

export function CommandCenter() {
 const { toast } = useApp();
 const [stage, setStage] = React.useState<string | null>(null);
 const [region, setRegion] = React.useState<string | null>(null);
 const [sport, setSport] = React.useState<string | null>(null);
 const [linkedAction, setLinkedAction] = React.useState<string | null>(null);
 const [drawer, setDrawer] = React.useState<CmdDrawerState | null>(null);

 const open = React.useCallback((kind: DrawerKind, data: any = null) => setDrawer({ kind, data }), []);
 const ctx = { stage, setStage, region, setRegion, sport, setSport, linkedAction, setLinkedAction, open, toast };

 return (
 <CommandContext.Provider value={ctx}>
 <div className="ci-fade">
 <CmdHeader />
 <div className="ci-grid">
 <KpiStrip />
 <PipelineRow />
 <MapRow />
 <VelocityRow />
 <MatrixRow />
 <OpportunitiesRow />
 <RisksRow />
 <ActionCenterRow />
 <AiInsightRow />
 <ActivityRow />
 </div>
 </div>
 <CmdDrawer state={drawer} onClose={() => setDrawer(null)}
 onAction={a => { toast(a + " — action started"); setDrawer(null); }} />
 </CommandContext.Provider>
 );
}
","/* ============================================================
 National Talent Radar — component styles (PREMIUM LIGHT)
 ============================================================ */

/* cohort builder filter chips */
.tr-builder { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
.tr-chip {
 display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px; border-radius: 999px;
 border: 1px dashed var(--ci-border-strong); background: #fff; color: var(--ci-text-dim);
 font-size: 11px; font-weight: 600; cursor: pointer; transition: all .14s ease; user-select: none;
}
.tr-chip:hover { border-color: var(--ci-cyan); color: var(--ci-cyan); }
.tr-chip--on { border-style: solid; border-color: var(--ci-cyan); background: var(--ci-cyan-soft); color: var(--ci-cyan); }

/* benchmark athlete rows */
.tr-bench { display: flex; flex-direction: column; gap: 8px; }
.tr-benchrow {
 border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); padding: 9px 11px;
 background: var(--ci-bg-0); cursor: pointer; transition: all .15s ease;
}
.tr-benchrow:hover { border-color: var(--ci-border-strong); background: var(--ci-bg-3); }
.tr-benchrow--sel { border-color: var(--ci-cyan); background: var(--ci-cyan-soft); }
.tr-benchrow__top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.tr-benchrow__name { font-size: 12.5px; font-weight: 700; color: var(--ci-text); }
.tr-benchrow__meta { font-size: 10.5px; color: var(--ci-text-faint); margin-top: 1px; }
.tr-gap { font-size: 12px; font-weight: 800; }

/* opportunity score gauge chip */
.tr-oppscore { display: flex; align-items: center; gap: 10px; padding: 9px 11px; border-radius: var(--ci-radius-sm);
 background: var(--ci-amber-soft); border: 1px solid rgba(217,130,10,0.22); margin-bottom: 10px; }
.tr-oppscore__num { font-size: 22px; font-weight: 800; color: var(--ci-amber); line-height: 1; }
.tr-oppscore__lab { font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ci-text-faint); font-weight: 700; }

/* cohort table tuning (reuses ci-table) */
.tr-table td, .tr-table th { padding: 7px 8px; }
.tr-pct { font-weight: 700; }
