import { BENCH_AXES, GLOBAL_BENCHMARK, regionDerived, NATIONAL_CONVERSION_AVG } from "../../../data/radar";

const stat = (v: React.ReactNode, l: string) => (
 <div className="ci-stat"><span className="ci-stat__v">{v}</span><span className="ci-stat__l">{l}</span></div>
);
const gapTone = (g: number) => (g >= -10 ? "var(--ci-green)" : g >= -16 ? "var(--ci-amber)" : "var(--ci-red)");

export function RadarDrawer({ state, onClose, onAction }:
 { state: RDrawerState | null; onClose: () => void; onAction: (a: string) => void }) {
 if (!state) return null;
 const { kind, data } = state;
 let title = "", sub = "", body: React.ReactNode = null, actions: string[] = [];

 if (kind === "region") {
 const d = regionDerived(data);
 title = data.name + " Region"; sub = `${data.discovered.toLocaleString()} discovered · opportunity ${d.opportunity}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(data.assessed.toLocaleString(), "Assessed")}
 {stat(data.highPotential, "High potential")}
 {stat(data.pathways.toLocaleString(), "Dev pathways")}
 {stat(`${d.coverage}%`, "Assessment coverage")}
 </div>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Top 3 sports · fastest {data.fastest}</div>
 <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>{data.top3.map((s: string, i: number) => <Chip key={s} status={i === 0 ? "cyan" : "ghost"}>{s}</Chip>)}</div>
 <div className="ci-insight"><span className="ci-insight__icon">◆</span><div className="ci-insight__txt" style={{ fontSize: 12 }}>{data.insight}
 {data.conversion < NATIONAL_CONVERSION_AVG && <> <b>({(NATIONAL_CONVERSION_AVG - data.conversion).toFixed(1)}pts below national average)</b></>}</div></div>
 </>;
 actions = ["View Athletes", "Create Cohort", "Launch Assessment", "Add to Watchlist"];
 } else if (kind === "athlete") {
 title = data.name; sub = `${data.sport} · ${data.region} · age ${data.age}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 12, marginBottom: 14 }}>
 {stat("P" + data.localPct, "Local pct")}
 {stat("P" + data.nationalPct, "National pct")}
 {stat(<span style={{ color: gapTone(data.globalGap) }}>{data.globalGap}%</span>, "Global gap")}
 </div>
 {data.attrs && <RadarChart axes={BENCH_AXES} size={230}
 profiles={[{ label: data.name, color: "#0a99c7", values: data.attrs }, GLOBAL_BENCHMARK]} />}
 {!data.attrs && <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.velocity >= 80 ? "Improving faster than cohort — strong candidate for accelerated assessment." : "Tracking within expected development band."} Current stage: <b style={{ color: "var(--ci-text)" }}>{data.stage}</b>.</p>}
 </>;
 actions = ["Open Athlete", "Compare", "Add to Watchlist", "Request Assessment"];
 } else if (kind === "opp") {
 title = data.tag; sub = "Talent opportunity";
 body = <>
 <div className="cc-opp__signal" style={{ marginBottom: 8 }}>{data.signal}</div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.why}</p>
 </>;
 actions = data.actions.concat(["Investigate"]);
 } else if (kind === "coh") {
 title = data.title || "Cohort"; sub = data.count != null ? `${data.count} athletes` : "Discovery cohort";
 body = <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>Save this cohort to track, compare and progress the selected athletes together, or request a batch assessment.</p>;
 actions = ["Add to Watchlist", "Request Assessment", "Create Intervention"];
 }

 return (
 <Drawer open onClose={onClose} title={title} sub={sub}
 footer={<ActionRow actions={actions} onAction={onAction} />}>{body}</Drawer>
 );
}
