 <div style={{ fontSize: 12.5, color: "var(--ci-text)", lineHeight: 1.5 }}>{it.t}</div>
 </div>
 <Button size="sm" variant="ghost" onClick={() => navigate("actions")}>Act</Button>
 </div>
 ))}
 </div>
 </Panel>

 <div className="ci-span-4" style={{ display: "flex", flexDirection: "column", gap: 14 }}>
 <Panel hover title="Model Confidence" sub="Prediction reliability by domain">
 {[["Talent identification", 91, "green"], ["Injury forecasting", 84, "green"], ["Transfer matching", 77, "amber"], ["Podium projection", 69, "amber"]].map(([l, v, c]: any) => (
 <div key={l} style={{ marginBottom: 10 }}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, marginBottom: 3 }}>
 <span className="ci-dim">{l}</span><span className="ci-num">{v}%</span>
 </div>
 <div className="ci-meter"><div className="ci-meter__fill" style={{ width: `${v}%`, background: `var(--ci-${c})` }} /></div>
 </div>
 ))}
 </Panel>
 <Panel hover title="Ask Champion IQ" sub="Natural-language intelligence">
 <div className="ci-search" style={{ minWidth: 0, marginBottom: 10 }}>
 <Icon.brain style={{ width: 15, height: 15 }} />
 <input placeholder="e.g. Who should we assess next?" aria-label="Ask AI" />
 </div>
 {["Which regions are under-scouted?", "Who is at risk of dropout?", "Best transfer candidates?"].map(q => (
 <div key={q} className="ci-filter__opt" style={{ borderRadius: 8, marginBottom: 2 }} onClick={() => toast("Analyzing: " + q)}>
 <Icon.search style={{ width: 12, height: 12 }} /> {q}
 </div>
 ))}
 </Panel>
 </div>
 </div>
 </div>
 );
}
","import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props { children?: ReactNode }
interface State { error: Error | null }

// App-wide safety net. A single throwing component must never blank the whole
// platform. Also surfaces the error message into document.title so it can be
// read from runtime diagnostics even when the DOM snapshot is truncated.
//
// NOTE: the inherited React.Component members are declared explicitly because
// this project's @types/react resolution does not surface them on subclasses.
// They are provided by React at runtime.
export class ErrorBoundary extends Component<Props, State> {
 declare props: Props;
 declare state: State;
 declare setState: (s: Partial<State>) => void;

 constructor(props: Props) {
 super(props);
 this.state = { error: null };
 }

 static getDerivedStateFromError(error: Error): State {
 try { document.title = "APPERR " + error.message; } catch { /* noop */ }
 return { error };
 }

 componentDidCatch(error: Error, info: ErrorInfo) {
 const frames = (info.componentStack || "")
 .split("\n").map(s => s.trim()).filter(Boolean).slice(0, 3).join(" <- ");
 try { document.title = "APPERR " + error.message + " :: " + frames; } catch { /* noop */ }
 console.error("[ErrorBoundary]", error, info.componentStack);
 }

 render() {
 const { error } = this.state;
 if (error) {
 return (
 <div style={{ padding: 24, fontFamily: "system-ui, sans-serif", color: "#0b2b3f" }}>
 <h2 style={{ margin: "0 0 8px" }}>Something went wrong rendering this view</h2>
 <pre style={{ whiteSpace: "pre-wrap", background: "#fff3f3", border: "1px solid #f0c0c0",
 borderRadius: 8, padding: 12, fontSize: 12.5, color: "#9b1c1c" }}>
 {error.message}
 {"\n\n"}
 {error.stack}
 </pre>
 </div>
 );
 }
 return <>{this.props.children}</>;
 }
}
","import React from "react";
import "./theme.css";
import "./app.css";
import "./components.css";
import { AppProvider, useApp } from "./context/AppContext";
import { Sidebar } from "./components/shell/Sidebar";
import { TopBar } from "./components/shell/TopBar";
import { FilterBar } from "./components/shell/FilterBar";
import { Toast, AthleteDrawer } from "./components/common";
import { CommandCenter } from "./components/views/CommandCenter";
import { TalentRadar } from "./components/views/TalentRadar";
import { Athletes } from "./components/views/Athletes";
import { Athlete360 } from "./components/views/Athlete360";
import { Performance, Wearables, ComputerVision } from "./components/views/Analytics";
import { GymEquipment, LabAssessments } from "./components/views/PerfExtra";
import { GlobalBenchmark, DevelopmentJourney } from "./components/views/BenchJourney";
import { Actions } from "./components/views/Actions";
import { AIIntelligence } from "./components/views/AIIntelligence";
import { Athlete } from "./data/demo";
import { ErrorBoundary } from "./components/ErrorBoundary";

function Router() {
 const { view } = useApp();
 const [athlete, setAthlete] = React.useState<Athlete | null>(null);
 const pick = (a: Athlete) => setAthlete(a);

 const render = () => {
 switch (view) {
 case "command": return <CommandCenter />;
 case "radar": return <TalentRadar />;
 case "athletes": return <Athletes onAthlete={pick} />;
 case "athlete360": return <Athlete360 />;
 case "performance": return <Performance onAthlete={pick} />;
 case "wearables": return <Wearables onAthlete={pick} />;
 case "vision": return <ComputerVision />;
 case "gym": return <GymEquipment onAthlete={pick} />;
 case "lab": return <LabAssessments onAthlete={pick} />;
 case "benchmark": return <GlobalBenchmark />;
 case "journey": return <DevelopmentJourney />;
 case "actions": return <Actions />;
 case "ai": return <AIIntelligence />;
 default: return <CommandCenter />;
 }
 };

 return (
 <div className="ci-shell">
 <Sidebar />
 <div className="ci-main">
 <TopBar />
 <FilterBar />
 <main className="ci-content">{render()}</main>
 </div>
 <AthleteDrawer athlete={athlete} onClose={() => setAthlete(null)} />
 <Toast />
 </div>
 );
}

export default function App() {
 return (
 <AppProvider>
 <div className="ci-app"><ErrorBoundary><Router /></ErrorBoundary></div>
 </AppProvider>
 );
}
